with ustacks. Ctrl-C to end.\n"); 
} 

tracepoint:syscalls:sys_enter_connect 
/args->uservaddr->sa_family == AF_INET || 
    args->uservaddr->sa_family == AF_INET6/ 
{ 
       @conn_start[tid] = nsecs; 
