                     $daddr = ntop( 
                         $sk-
>__sk_common.skc_v6_daddr.in6_u.u6_addr8); 
                     $saddr = ntop( 
                         $sk-
>__sk_common.skc_v6_rcv_saddr.in6_u.u6_addr8);

              }

              $lport = $sk-
>__sk_common.skc_num; 
              $dport = $sk-
>__sk_common.skc_dport; 

              // Destination port is big 
endian, it must be flipped 
              $dport = ($dport >> 8) | 
(($dport << 8) & 0x00FF00); 

              $state = $sk-
>__sk_common.skc_state; 
              $statestr = 
@tcp_states[$state]; 

              time("%H:%M:%S "); 
              printf("%-8d %14s:%-6d 
%14s:%-6d %6s\n", pid, $saddr, $lport, 
                  $daddr, $dport, 
$statestr); 
