kretprobe:xen_steal_clock, 
kretprobe:kvm_steal_clock 
{ 
       if (@last[cpu] > 0) { 
              @stolen_us = hist((retval - 
@last[cpu]) / 1000); 
       } 
       @last[cpu] = retval; 
} 

END 
